$q=trim((string)($_GET['q']??''));$page=max(1,(int)($_GET['p']??1));$per=50;$where=array('1=1');$types='';$params=array();$char=$PCC->tableExists('rp_characters');$profile=$PCC->tableExists('rp_inventory_profiles');$joins=' LEFT JOIN rp_inventory_items i ON i.owner_user_id=u.id LEFT JOIN rp_item_definitions d ON d.id=i.item_definition_id';if($profile)$joins.=' LEFT JOIN rp_inventory_profiles pr ON pr.user_id=u.id';if($char)$joins.=' LEFT JOIN rp_characters c ON c.user_id=u.id';if($q!==''){$like='%'.mb_substr($q,0,64).'%';$bits=array('u.username LIKE ?','CAST(u.id AS CHAR)=?');$types.='ss';$params[]=$like;$params[]=$q;if($char){$bits[]='c.citizen_id LIKE ?';$bits[]="CONCAT(COALESCE(c.first_name,''),' ',COALESCE(c.last_name,'')) LIKE ?";$types.='ss';$params[]=$like;$params[]=$like;}$where[]='('.implode(' OR ',$bits).')';}
$count=$DB->PreparedRow('SELECT COUNT(*) total FROM users u WHERE EXISTS(SELECT 1 FROM rp_inventory_items ii WHERE ii.owner_user_id=u.id)'.($q!==''?' AND u.id IN (SELECT ux.id FROM users ux'.($char?' LEFT JOIN rp_characters cx ON cx.user_id=ux.id':'').' WHERE '.($char?'ux.username LIKE ? OR CAST(ux.id AS CHAR)=? OR cx.citizen_id LIKE ? OR CONCAT(COALESCE(cx.first_name,\'\'),\' \',COALESCE(cx.last_name,\'\')) LIKE ?':'ux.username LIKE ? OR CAST(ux.id AS CHAR)=?').')':''),$q!==''?($char?'ssss':'ss'):'',$q!==''?($char?array($like,$q,$like,$like):array($like,$q)):array());$total=$count?(int)$count['total']:0;$pages=max(1,(int)ceil($total/$per));if($page>$pages)$page=$pages;$offset=($page-1)*$per;
$cols='u.id,u.username,u.look,u.online,COUNT(i.id) stacks,COALESCE(SUM(i.quantity),0) quantity,COALESCE(SUM(i.quantity*d.weight),0) weight'.($profile?',COALESCE(pr.base_capacity,50)+COALESCE(pr.capacity_bonus,0) capacity,COALESCE(pr.max_slots,30) max_slots':',50 capacity,30 max_slots').($char?',c.first_name,c.last_name,c.citizen_id':',NULL first_name,NULL last_name,NULL citizen_id');$sql='SELECT '.$cols.' FROM users u'.$joins.' WHERE '.implode(' AND ',$where).' GROUP BY u.id HAVING COUNT(i.id)>0 ORDER BY u.username LIMIT '.$per.' OFFSET '.(int)$offset;$rows=$DB->PreparedAll($sql,$types,$params);$link=function($p)use($q){return URL.'/admin.php?'.http_build_query(array('page'=>'inventory','q'=>$q,'p'=>$p));};
