<section class="pcc-panel"><form class="pcc-filterbar"><input type="hidden" name="page" value="inventory"><div class="pcc-search-field"><i class="fas fa-search"></i><input name="q" value="<?php echo $h($q);?>" placeholder="Joueur, ID, Citizen ID…"></div><button class="pcc-button secondary">Rechercher</button><span class="pcc-filter-count"><?php echo $number($total);?> inventaire(s)</span></form><div class="pcc-table-wrap"><table class="pcc-table"><thead><tr><th>Joueur</th><th>Nom RP</th><th>Citizen ID</th><th>Stacks</th><th>Quantité totale</th><th>Poids</th><th>Capacité</th><th>Slots</th><th>Statut</th><th></th></tr></thead><tbody><?php if(!$rows):?><tr><td colspan="10"><div class="pcc-empty compact"><strong>Aucun inventaire trouvé</strong></div></td></tr><?php endif;?><?php foreach($rows as $r):$rp=trim((string)$r['first_name'].' '.(string)$r['last_name']);?><tr><td><div class="pcc-user-cell"><img class="pcc-table-avatar" src="<?php echo $h($PCC->avatarUrl($r['look'],'s'));?>" alt=""><span><strong><?php echo $h($r['username']);?></strong><small class="pcc-subline">#<?php echo (int)$r['id'];?></small></span></div></td><td><?php echo $rp!==''?$h($rp):'—';?></td><td><code><?php echo $r['citizen_id']?$h($r['citizen_id']):'—';?></code></td><td><?php echo (int)$r['stacks'];?></td><td><?php echo (int)$r['quantity'];?></td><td><?php echo $h(number_format((float)$r['weight'],3,',',' '));?> kg</td><td><?php echo $h(number_format((float)$r['capacity'],3,',',' '));?> kg</td><td><?php echo (int)$r['stacks'];?> / <?php echo (int)$r['max_slots'];?></td><td><span class="pcc-badge <?php echo (int)$r['online']===1?'success':'';?>"><?php echo (int)$r['online']===1?'EN LIGNE':'HORS LIGNE';?></span></td><td><a class="pcc-button small secondary" href="<?php echo URL;?>/admin.php?page=player&id=<?php echo (int)$r['id'];?>&tab=inventory">Ouvrir</a></td></tr><?php endforeach;?></tbody></table></div><?php if($pages>1):?><div class="pcc-pagination"><?php if($page>1):?><a href="<?php echo $h($link($page-1));?>">‹</a><?php endif;?><?php for($i=max(1,$page-2);$i<=min($pages,$page+2);$i++):?><a class="<?php echo $i===$page?'is-active':'';?>" href="<?php echo $h($link($i));?>"><?php echo $i;?></a><?php endfor;?><?php if($page<$pages):?><a href="<?php echo $h($link($page+1));?>">›</a><?php endif;?></div><?php endif;?></section>
